<script setup>import {ref} from 'vue';import {post} from '../api/client';const props=defineProps({token:String}),emit=defineEmits(['done']),password=ref(''),confirm=ref(''),message=ref('');async function save(){if(password.value!==confirm.value){message.value='两次密码不一致';return}try{await post('/auth/reset-password',{token:props.token,new_password:password.value});message.value='密码重置成功';setTimeout(()=>emit('done'),800)}catch(e){message.value=e.message}}</script><template><div class="auth-page"><form class="auth-card card" @submit.prevent="save"><h1>重置密码</h1><p class="hint">新密码至少10位，并同时包含字母和数字。</p><label>新密码<input v-model="password" type="password"></label><label>确认密码<input v-model="confirm" type="password"></label><p v-if="message" class="notice">{{message}}</p><button>重置密码</button></form></div></template>
